using DAL;
using Microsoft.Extensions.DependencyInjection;
using Utils;
using Utils.Interface;
using System.Text.Json.Nodes;
namespace Tests;
public class AdminPayoutTests(ApiFactory f):ApiTest(f)
{
    [Fact]public async Task List_filters_due_totals_snapshot_redaction_and_changed_bank_by_plaintext()
    {
        var admin=await Admin();var user=await LoginPhone("9890000099");Assert.Equal(403,(await user.Get("/api/admin/payouts")).Status);Assert.Equal(422,(await admin.Get("/api/admin/payouts?page=0")).Status);var seller=(await user.Post("/api/seller/register",new{display_name="Synthetic Payout Store"})).Json["id"]!.GetValue<string>();using var scope=Factory.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<IMySqlDapperHelper>();var ledger=scope.ServiceProvider.GetRequiredService<LedgerDAL>();var crypto=scope.ServiceProvider.GetRequiredService<EncryptDecrypt>();var enc=crypto.Encrypt("123456789012");await ApiFactory.DbExecAsync("UPDATE sellers SET bank_account_enc=@enc,bank_holder_name='Synthetic Holder',bank_ifsc='SYNT0001234',bank_account_last4='9012' WHERE id=@seller",new{enc,seller});var now=DateTime.UtcNow;var ids=new[]{Guid.NewGuid(),Guid.NewGuid()};await using(var tx=await db.BeginAsync())
        {for(var i=0;i<2;i++)await ledger.InsertPayoutAsync(new(){Id=ids[i],Number="SYNTH-PAYOUT-"+i,SellerId=Guid.Parse(seller),Amount=10000,Status=i==0?"pending":"paid",Mode="manual",BankSnapshot=new JsonObject{["holder"]="Synthetic Holder",["account_enc"]=crypto.Encrypt("123456789012"),["account_last4"]="9012",["ifsc"]="SYNT0001234"}.ToJsonString(),CreatedAt=now.AddMinutes(i),UpdatedAt=now},tx);await tx.CommitAsync();}
        for(var i=0;i<3;i++)await ApiFactory.DbExecAsync("INSERT INTO seller_ledger(id,seller_id,kind,amount,description,available_at,created_at)VALUES(@id,@seller,'adjustment',@amount,'Synthetic',@available,@now)",new{id=Guid.NewGuid(),seller,amount=i==0?1000:i==1?-200:5000,available=i==2?now.AddDays(1):now.AddSeconds(-1),now});var r=await admin.Get("/api/admin/payouts");Assert.True(r.Status==200,r.ToString());Assert.Equal(2,r.Json["total"]!.GetValue<long>());Assert.Equal(800,r.Json["due"]![0]!["amount"]!.GetValue<long>());Assert.Equal("paid",r.Json["items"]![0]!["status"]!.GetValue<string>());Assert.Equal("Synthetic Payout Store",r.Json["items"]![1]!["seller_name"]!.GetValue<string>());Assert.False(r.Json["items"]![1]!["bank_changed"]!.GetValue<bool>());Assert.Null(r.Json["items"]![1]!["bank"]!["account_enc"]);Assert.DoesNotContain("123456789012",r.ToString());Assert.Single((await admin.Get("/api/admin/payouts?status=pending&seller_id="+seller)).Json["items"]!.AsArray());Assert.Empty((await admin.Get("/api/admin/payouts?seller_id="+Guid.NewGuid())).Json["items"]!.AsArray());Assert.Equal(2,(await admin.Get("/api/admin/payouts?status=")).Json["total"]!.GetValue<long>());
        enc=crypto.Encrypt("123456780000");await ApiFactory.DbExecAsync("UPDATE sellers SET bank_account_enc=@enc WHERE id=@seller",new{enc,seller});r=await admin.Get("/api/admin/payouts");Assert.True(r.Json["items"]![1]!["bank_changed"]!.GetValue<bool>());Assert.False(r.Json["items"]![0]!["bank_changed"]!.GetValue<bool>());await ApiFactory.DbExecAsync("UPDATE payouts SET bank_snapshot=JSON_OBJECT('holder','Legacy') WHERE id=@id",new{id=ids[0]});r=await admin.Get("/api/admin/payouts?status=pending");Assert.False(r.Json["items"]![0]!["bank_changed"]!.GetValue<bool>());Assert.Equal(50,r.Json["page_size"]!.GetValue<int>());
    }
}
